#!/usr/bin/env node
// GENERATED by stapel-tools (stapel_tools/data/ui-wiring.mjs) — static UI wiring check.
// ui-wiring protocol 2
//
// usage: node scripts/ui-wiring.mjs [--frontend <dir>] [--api-base </slug/api>] <manifest.json | dir>
//
// A manifest names, per criterion, the pages of the SPA: route, h1, testids and
// actions ({testid, handler: click|submit|change, request: {method, path}}).
// Read with the TypeScript compiler API over <frontend>/src (tests excluded):
//   route    a router route object (`path` beside element/Component/lazy/children)
//            or <Route path> equal to the route (params as wildcards)
//   testid   rendered by exactly one module (data-testid literal)
//   h1       the module of the page's first testid renders <h1> or an antd Title of level 1
//   handler  the action's element carries onClick/to/href (click), onSubmit/onFinish
//            (submit) or onChange (change), or is a submit button inside such a form;
//            a handler that is a prop of its component is followed one level up to
//            the JSX that renders the component and must be passed there
//   request  the element's module, a module it imports (two hops), or the module that
//            passes the handler prop, issues the FULL request path, base included, and,
//            unless GET, the method. Paths are evaluated from constant parts: string and
//            template literals, `+`, module and imported consts, object-literal members,
//            import.meta.env.* from the frontend's .env files with `??`/`||` defaults,
//            helpers that prefix a parameter (`(p) => fetch(`${BASE}${p}`)`) and clients
//            created with a baseURL/baseUrl/prefixUrl. A request a @stapel/* pair issues
//            passes when that pair's manifest.json declares the operation.
//   base     every API path (one with an /api segment) in a page's scope sits under the
//            project's canon (--api-base, the manifest's api_base, the bases of its
//            requests) or a base a @stapel/* pair declares
// UNVERIFIABLE (never green, exit 3) where a value cannot be resolved statically: a base
// built from a runtime value, a handler from {...spread} props, a handler prop of a
// component rendered nowhere in src/, a request inside a pair with no manifest.
// It cannot see: dead code (a wired path that is never called still counts), a
// handler that calls the wrong function of the right module, requests built in a
// helper more than one level deep, components handed around as values.
//
// Output: one PASS/FAIL/UNVERIFIABLE line per check, a count line, and a final
// `UI_WIRING_RESULT <json>` line. Exit 0 green, 1 red, 3 unverifiable only,
// 2 the check could not run.
import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";

const RESULT_TAG = "UI_WIRING_RESULT";
const ERROR_TAG = "UI_WIRING_ERROR";
const PROTOCOL = 2;

function fail(message) {
  console.log(`${ERROR_TAG} ${message}`);
  console.log(`${RESULT_TAG} ${JSON.stringify({ ok: false, error: message, checks: 0, protocol: PROTOCOL })}`);
  process.exit(2);
}

function parseArgs(argv) {
  let frontend = ".";
  let apiBase = "";
  const rest = [];
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === "--frontend") {
      frontend = argv[i + 1] ?? "";
      i += 1;
    } else if (argv[i] === "--api-base") {
      apiBase = argv[i + 1] ?? "";
      i += 1;
    } else {
      rest.push(argv[i]);
    }
  }
  if (rest.length !== 1 || !frontend) {
    fail("usage: ui-wiring.mjs [--frontend <dir>] [--api-base <base>] <manifest.json | dir>");
  }
  return { frontend: path.resolve(frontend), apiBase: normBase(apiBase), manifest: path.resolve(rest[0]) };
}

function normBase(base) {
  const b = String(base || "").trim().replace(/\/+$/, "");
  return b && !b.startsWith("/") ? `/${b}` : b;
}

function loadTypeScript(frontend) {
  const candidates = [];
  if (process.env.UI_WIRING_TYPESCRIPT) candidates.push(process.env.UI_WIRING_TYPESCRIPT);
  candidates.push("typescript");
  const req = createRequire(path.join(frontend, "package.json"));
  for (const name of candidates) {
    try {
      return req(name);
    } catch {
      // next candidate
    }
  }
  return fail(`typescript is not installed under ${frontend} (run the frontend install first)`);
}

function loadManifests(target) {
  if (!fs.existsSync(target)) fail(`manifest not found: ${target}`);
  const files = fs.statSync(target).isDirectory()
    ? fs.readdirSync(target).filter((f) => f.endsWith(".json")).sort().map((f) => path.join(target, f))
    : [target];
  const out = [];
  for (const file of files) {
    let data;
    try {
      data = JSON.parse(fs.readFileSync(file, "utf8"));
    } catch (e) {
      fail(`manifest ${file} is not JSON: ${e.message}`);
    }
    if (!data || !Array.isArray(data.criteria)) fail(`manifest ${file} has no criteria list`);
    out.push({ file, data });
  }
  return out;
}

const SOURCE_RE = /\.(tsx?|jsx?|mjs)$/;
const TEST_RE = /(\.test\.|\.spec\.|__tests__)/;

function walk(dir, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === "node_modules" || entry.name.startsWith(".")) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, out);
    else if (SOURCE_RE.test(entry.name) && !TEST_RE.test(full)) out.push(full);
  }
  return out;
}

// Vite's production precedence: .env.production.local > .env.production > .env.local > .env
function loadEnv(frontend) {
  const env = {};
  for (const name of [".env", ".env.local", ".env.production", ".env.production.local"]) {
    const file = path.join(frontend, name);
    if (!fs.existsSync(file)) continue;
    for (const raw of fs.readFileSync(file, "utf8").split(/\r?\n/)) {
      const m = raw.match(/^\s*(?:export\s+)?([A-Za-z_][\w]*)\s*=\s*(.*)\s*$/);
      if (!m) continue;
      env[m[1]] = m[2].replace(/^(['"])(.*)\1$/, "$2");
    }
  }
  return env;
}

// Unknown parts of an evaluated string: a runtime value, or the page origin.
const UNKNOWN = "\u0001";
const ORIGIN = "\u0002";

function scan(ts, file, root) {
  const text = fs.readFileSync(file, "utf8");
  const kind = file.endsWith(".tsx") || file.endsWith(".jsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS;
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, kind);
  const mod = {
    file,
    rel: path.relative(root, file).split(path.sep).join("/"),
    sf,
    testids: [],
    literals: [],
    routes: [],
    imports: [],
    bindings: new Map(), // local name -> {spec, name: imported name | "default" | "*"}
    consts: new Map(), // top-level const name -> initializer
    functions: new Map(), // function name -> function-like node
    sites: [], // maximal string expressions
    calls: [],
    jsx: [], // capitalized JSX elements: {tag, element, line}
    methodCalls: new Set(),
    h1: false,
  };
  const lineOf = (node) => sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1;
  mod.lineOf = lineOf;
  const literalText = (node) => {
    if (!node) return undefined;
    if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) return node.text;
    if (ts.isJsxExpression(node)) return literalText(node.expression);
    if (ts.isParenthesizedExpression(node)) return literalText(node.expression);
    return undefined;
  };
  for (const stmt of sf.statements) {
    if (ts.isVariableStatement(stmt) && (stmt.declarationList.flags & ts.NodeFlags.Const)) {
      for (const d of stmt.declarationList.declarations) {
        if (ts.isIdentifier(d.name) && d.initializer) {
          mod.consts.set(d.name.text, d.initializer);
          if (ts.isArrowFunction(d.initializer) || ts.isFunctionExpression(d.initializer)) {
            mod.functions.set(d.name.text, d.initializer);
          }
        }
      }
    }
    if (ts.isFunctionDeclaration(stmt) && stmt.name) mod.functions.set(stmt.name.text, stmt);
  }
  const isStringish = (node) => ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)
    || ts.isTemplateExpression(node);
  const visit = (node) => {
    if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) {
      mod.literals.push(node.text);
    }
    // A site is a string expression no larger string expression contains.
    const parent = node.parent;
    const inConcat = parent && ts.isBinaryExpression(parent)
      && parent.operatorToken.kind === ts.SyntaxKind.PlusToken;
    if (!inConcat) {
      if (isStringish(node) && !ts.isImportDeclaration(parent) && !ts.isExportDeclaration(parent)
          && !(parent && ts.isLiteralTypeNode(parent))) {
        mod.sites.push(node);
      } else if (ts.isBinaryExpression(node) && node.operatorToken.kind === ts.SyntaxKind.PlusToken) {
        mod.sites.push(node);
      }
    }
    if ((ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) && node.moduleSpecifier
        && ts.isStringLiteral(node.moduleSpecifier)) {
      const spec = node.moduleSpecifier.text;
      mod.imports.push(spec);
      const clause = ts.isImportDeclaration(node) ? node.importClause : undefined;
      if (clause) {
        if (clause.name) mod.bindings.set(clause.name.text, { spec, name: "default" });
        const nb = clause.namedBindings;
        if (nb && ts.isNamespaceImport(nb)) mod.bindings.set(nb.name.text, { spec, name: "*" });
        if (nb && ts.isNamedImports(nb)) {
          for (const el of nb.elements) {
            mod.bindings.set(el.name.text, { spec, name: (el.propertyName ?? el.name).text });
          }
        }
      }
    }
    if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword
        && node.arguments.length && ts.isStringLiteral(node.arguments[0])) {
      mod.imports.push(node.arguments[0].text);
    }
    if (ts.isCallExpression(node)) {
      mod.calls.push(node);
      if (ts.isPropertyAccessExpression(node.expression)) {
        mod.methodCalls.add(node.expression.name.text.toLowerCase());
      }
    }
    if (ts.isJsxAttribute(node)) {
      const name = node.name.getText(sf);
      const value = literalText(node.initializer);
      if (name === "data-testid" && value !== undefined) {
        mod.testids.push({ id: value, line: lineOf(node), element: jsxElementOf(ts, node) });
      }
      if (name === "path" && value !== undefined) {
        const owner = jsxElementOf(ts, node);
        if (owner && /(^|\.)Route$/.test(owner.tagName.getText(sf))) mod.routes.push(value);
      }
    }
    if (ts.isPropertyAssignment(node)) {
      const key = node.name && (ts.isIdentifier(node.name) || ts.isStringLiteral(node.name))
        ? node.name.text : "";
      const value = literalText(node.initializer);
      if (key === "path" && value !== undefined && isRouteObject(ts, node.parent)) {
        mod.routes.push(value);
      }
      if (key === "data-testid" && value !== undefined) {
        mod.testids.push({ id: value, line: lineOf(node), element: undefined });
      }
    }
    if (ts.isJsxOpeningElement(node) || ts.isJsxSelfClosingElement(node)) {
      const tag = node.tagName.getText(sf);
      if (tag === "h1") mod.h1 = true;
      if (tag === "Typography.Title" || tag === "Title") {
        const level = attribute(ts, node, "level");
        const levelText = level && level.initializer ? level.initializer.getText(sf) : "";
        if (!level || /^\{?\s*1\s*\}?$/.test(levelText)) mod.h1 = true;
      }
      if (/^[A-Z]/.test(tag)) mod.jsx.push({ tag, element: node, line: lineOf(node) });
    }
    ts.forEachChild(node, visit);
  };
  visit(sf);
  return mod;
}

// A react-router route object: `path` beside what the router renders (a nav
// manifest entry carries a path too, and declares no route).
const ROUTE_KEYS = new Set(["element", "Component", "lazy", "children", "index", "loader"]);

function isRouteObject(ts, objectLiteral) {
  if (!objectLiteral || !ts.isObjectLiteralExpression(objectLiteral)) return false;
  return objectLiteral.properties.some((p) => p.name
    && (ts.isIdentifier(p.name) || ts.isStringLiteral(p.name)) && ROUTE_KEYS.has(p.name.text));
}

function jsxElementOf(ts, attributeNode) {
  let node = attributeNode.parent;
  while (node && !ts.isJsxOpeningElement(node) && !ts.isJsxSelfClosingElement(node)) node = node.parent;
  return node;
}

function attribute(ts, element, name) {
  if (!element || !element.attributes) return undefined;
  return element.attributes.properties.find(
    (p) => ts.isJsxAttribute(p) && p.name.getText() === name,
  );
}

function attributeValue(ts, element, name) {
  const attr = attribute(ts, element, name);
  if (!attr || !attr.initializer) return undefined;
  if (ts.isStringLiteral(attr.initializer)) return attr.initializer.text;
  const expr = attr.initializer.expression;
  if (expr && (ts.isStringLiteral(expr) || ts.isNoSubstitutionTemplateLiteral(expr))) return expr.text;
  return undefined;
}

function resolveImport(fromFile, spec, known) {
  if (!spec.startsWith(".")) return undefined;
  const base = path.resolve(path.dirname(fromFile), spec);
  const stem = base.replace(/\.(m?js|jsx|tsx?)$/, "");
  const tries = [base, `${stem}.ts`, `${stem}.tsx`, `${stem}.js`, `${stem}.jsx`, `${stem}.mjs`,
    path.join(base, "index.ts"), path.join(base, "index.tsx"), path.join(base, "index.js")];
  return tries.find((t) => known.has(t));
}

// ─── constant evaluation ─────────────────────────────────────────────────────
// A value is a list of parts: strings, or {u: reason} for what is not constant
// ({origin: true} for the page origin, {env: name} for an unset env variable,
// {param: name} for a helper's parameter).

class Evaluator {
  constructor(ts, byFile, env) {
    this.ts = ts;
    this.byFile = byFile;
    this.env = env;
  }

  module(mod, spec) {
    const target = resolveImport(mod.file, spec, this.byFile);
    return target ? this.byFile.get(target) : undefined;
  }

  // The declaration an identifier names: [module, node, kind] or undefined.
  lookup(mod, name, depth = 0) {
    if (depth > 4) return undefined;
    if (mod.consts.has(name)) return { mod, node: mod.consts.get(name) };
    if (mod.functions.has(name)) return { mod, node: mod.functions.get(name) };
    const b = mod.bindings.get(name);
    if (!b || b.name === "*" || b.name === "default") return undefined;
    const target = this.module(mod, b.spec);
    return target ? this.lookup(target, b.name, depth + 1) : undefined;
  }

  evaluate(mod, node, scope = new Map(), depth = 0) {
    const ts = this.ts;
    const unknown = (reason) => [{ u: reason }];
    if (!node || depth > 8) return unknown("too deep");
    if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) return [node.text];
    if (ts.isTemplateExpression(node)) {
      const out = [node.head.text];
      for (const span of node.templateSpans) {
        out.push(...this.evaluate(mod, span.expression, scope, depth + 1), span.literal.text);
      }
      return out;
    }
    if (ts.isParenthesizedExpression(node) || ts.isAsExpression(node) || ts.isNonNullExpression(node)
        || (ts.isSatisfiesExpression && ts.isSatisfiesExpression(node)) || ts.isTypeAssertionExpression?.(node)) {
      return this.evaluate(mod, node.expression, scope, depth + 1);
    }
    if (ts.isBinaryExpression(node)) {
      const op = node.operatorToken.kind;
      if (op === ts.SyntaxKind.PlusToken) {
        return [...this.evaluate(mod, node.left, scope, depth + 1),
          ...this.evaluate(mod, node.right, scope, depth + 1)];
      }
      if (op === ts.SyntaxKind.QuestionQuestionToken || op === ts.SyntaxKind.BarBarToken) {
        const left = this.evaluate(mod, node.left, scope, depth + 1);
        if (known(left)) return left;
        if (left.length === 1 && left[0].env) return this.evaluate(mod, node.right, scope, depth + 1);
        return unknown(node.getText(mod.sf).slice(0, 60));
      }
    }
    if (ts.isIdentifier(node)) {
      if (scope.has(node.text)) return scope.get(node.text);
      const decl = this.lookup(mod, node.text);
      if (decl && !ts.isFunctionLike(decl.node)) return this.evaluate(decl.mod, decl.node, new Map(), depth + 1);
      return unknown(node.text);
    }
    if (ts.isPropertyAccessExpression(node)) {
      const text = node.getText(mod.sf);
      const env = text.match(/^import\.meta\.env\.([A-Za-z_]\w*)$/);
      if (env) return env[1] in this.env ? [this.env[env[1]]] : [{ u: `env ${env[1]}`, env: env[1] }];
      if (/^(window\.)?location\.origin$/.test(text)) return [{ u: "origin", origin: true }];
      const owner = node.expression;
      if (ts.isIdentifier(owner)) {
        const b = mod.bindings.get(owner.text);
        if (b && b.name === "*") {
          const target = this.module(mod, b.spec);
          const decl = target && this.lookup(target, node.name.text);
          if (decl) return this.evaluate(decl.mod, decl.node, new Map(), depth + 1);
        }
        const decl = this.lookup(mod, owner.text);
        if (decl && ts.isObjectLiteralExpression(decl.node)) {
          const prop = decl.node.properties.find((p) => ts.isPropertyAssignment(p) && p.name
            && (ts.isIdentifier(p.name) || ts.isStringLiteral(p.name)) && p.name.text === node.name.text);
          if (prop) return this.evaluate(decl.mod, prop.initializer, new Map(), depth + 1);
        }
      }
      return unknown(text.slice(0, 60));
    }
    return unknown(node.getText(mod.sf).slice(0, 60));
  }
}

function known(parts) {
  return parts.every((p) => typeof p === "string");
}

function flatten(parts) {
  return parts.map((p) => (typeof p === "string" ? p : p.origin ? ORIGIN : UNKNOWN)).join("");
}

function describe(parts) {
  return parts.map((p) => (typeof p === "string" ? p : `\${${p.u}}`)).join("");
}

const CLIENT_FACTORIES = /^(create|createClient|createApi|createFetch|createHttp)$/;
const BASE_KEYS = new Set(["baseURL", "baseUrl", "prefixUrl", "base"]);
const CLIENT_METHODS = new Set(["get", "post", "put", "patch", "delete", "head", "options", "request",
  "fetch", "GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"]);

// Helpers that prefix a parameter, and clients created with a base.
function findHelpers(ts, mods, ev) {
  for (const mod of mods) {
    mod.helpers = new Map(); // function name -> {index, prefix}
    mod.clients = new Map(); // const name -> {prefix}
  }
  for (let pass = 0; pass < 2; pass += 1) {
    for (const mod of mods) {
      for (const [name, fn] of mod.functions) {
        if (mod.helpers.has(name) || !fn.parameters) continue;
        fn.parameters.forEach((param, index) => {
          if (mod.helpers.has(name) || !ts.isIdentifier(param.name)) return;
          const pname = param.name.text;
          const scope = new Map([[pname, [{ u: pname, param: pname }]]]);
          const visit = (node) => {
            if (mod.helpers.has(name)) return;
            if ((ts.isTemplateExpression(node) || (ts.isBinaryExpression(node)
                && node.operatorToken.kind === ts.SyntaxKind.PlusToken))) {
              const parts = applyHelper(ts, mod, ev, node, ev.evaluate(mod, node, scope));
              const at = parts.findIndex((p) => p.param === pname);
              if (at > 0) {
                mod.helpers.set(name, { index, prefix: parts.slice(0, at) });
                return;
              }
            }
            ts.forEachChild(node, visit);
          };
          if (fn.body) visit(fn.body);
        });
      }
      for (const [name, init] of mod.consts) {
        if (mod.clients.has(name) || !ts.isCallExpression(init)) continue;
        const callee = init.expression;
        const fname = ts.isPropertyAccessExpression(callee) ? callee.name.text
          : ts.isIdentifier(callee) ? callee.text : "";
        if (!CLIENT_FACTORIES.test(fname)) continue;
        const opts = init.arguments[0];
        if (!opts || !ts.isObjectLiteralExpression(opts)) continue;
        const prop = opts.properties.find((p) => ts.isPropertyAssignment(p) && p.name
          && (ts.isIdentifier(p.name) || ts.isStringLiteral(p.name)) && BASE_KEYS.has(p.name.text));
        if (prop) mod.clients.set(name, { prefix: ev.evaluate(mod, prop.initializer) });
      }
    }
  }
}

function lookupIn(mod, name, table, ev, depth = 0) {
  if (depth > 4) return undefined;
  if (mod[table] && mod[table].has(name)) return mod[table].get(name);
  const b = mod.bindings.get(name);
  if (!b || b.name === "*" || b.name === "default") return undefined;
  const target = ev.module(mod, b.spec);
  return target ? lookupIn(target, b.name, table, ev, depth + 1) : undefined;
}

// The prefix a call adds to the string at argument position of *node*.
function prefixFor(ts, mod, ev, node) {
  const call = node.parent;
  if (!call || !ts.isCallExpression(call)) return undefined;
  const index = call.arguments.indexOf(node);
  if (index < 0) return undefined;
  const callee = call.expression;
  if (ts.isIdentifier(callee)) {
    const helper = lookupIn(mod, callee.text, "helpers", ev);
    if (helper && helper.index === index) return { prefix: helper.prefix, via: callee.text };
  }
  if (ts.isPropertyAccessExpression(callee) && ts.isIdentifier(callee.expression) && index === 0
      && CLIENT_METHODS.has(callee.name.text)) {
    const client = lookupIn(mod, callee.expression.text, "clients", ev);
    if (client) return { prefix: client.prefix, via: callee.expression.text };
  }
  return undefined;
}

function applyHelper(ts, mod, ev, node, parts) {
  const found = prefixFor(ts, mod, ev, node);
  return found ? [...found.prefix, ...parts] : parts;
}

// Every string site of a module, evaluated with the prefix of the call it feeds.
function evaluateSites(ts, mods, ev) {
  for (const mod of mods) {
    mod.paths = [];
    for (const site of mod.sites) {
      const raw = site.getText(mod.sf);
      if (!raw.includes("/") && !ts.isBinaryExpression(site) && !ts.isTemplateExpression(site)) continue;
      const parts = applyHelper(ts, mod, ev, site, ev.evaluate(mod, site));
      const flat = flatten(parts);
      if (!flat.includes("/")) continue;
      mod.paths.push({ parts, flat, line: mod.lineOf(site) });
    }
  }
}

function reachable(mods, byFile, hops) {
  const seen = new Map(mods.map((m) => [m.file, m]));
  let frontier = [...mods];
  for (let i = 0; i < hops; i += 1) {
    const next = [];
    for (const m of frontier) {
      for (const spec of m.imports) {
        const target = resolveImport(m.file, spec, byFile);
        if (target && !seen.has(target)) {
          seen.set(target, byFile.get(target));
          next.push(byFile.get(target));
        }
      }
    }
    frontier = next;
  }
  return [...seen.values()];
}

function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const PARAM_RE = /(<[^>/]+>|\{[^}/]+\}|:[A-Za-z_][\w]*)/g;
const END = `/?(?:$|\\?|${UNKNOWN})`;

function pathPattern(p) {
  return p.replace(/\/+$/, "").split(PARAM_RE).map((part, i) => (i % 2 ? `[^/?]+` : escapeRe(part))).join("");
}

function splitBase(p) {
  const at = p.indexOf("/api/");
  if (at >= 0) return { base: p.slice(0, at + 4), tail: p.slice(at + 4) };
  if (p.endsWith("/api")) return { base: p, tail: "" };
  return { base: "", tail: p };
}

function requestNeedle(requestPath) {
  const full = String(requestPath || "").split("?")[0];
  const { base, tail } = splitBase(full);
  return {
    full,
    base,
    tail,
    fullRe: new RegExp(`^(?:https?://[^/${UNKNOWN}]+|${ORIGIN})?${pathPattern(full)}${END}`),
    tailRe: new RegExp(`${pathPattern(tail)}${END}`),
  };
}

function holdsMethod(mod, method) {
  const m = String(method || "GET").toUpperCase();
  if (m === "GET") return true;
  return mod.literals.some((s) => s.toUpperCase() === m) || mod.methodCalls.has(m.toLowerCase());
}

// How each path value in *scope* relates to the needle.
function classify(scope, needle, method) {
  const out = { exact: [], wrongBase: [], unverifiable: [] };
  for (const mod of scope) {
    for (const p of mod.paths) {
      const where = `${mod.rel}:${p.line}`;
      if (needle.fullRe.test(p.flat)) {
        if (holdsMethod(mod, method)) out.exact.push(where);
        continue;
      }
      const m = needle.tail ? needle.tailRe.exec(p.flat) : null;
      if (!m) continue;
      const prefix = p.flat.slice(0, m.index);
      const prefixParts = describe(p.parts).slice(0, describe(p.parts).indexOf(needle.tail.replace(/\/+$/, "")));
      if (prefix.includes(UNKNOWN) || prefix.includes(ORIGIN) || prefix === "") {
        out.unverifiable.push(`${where} builds ${describe(p.parts)} (base ${prefixParts || "not in the string"} is not constant)`);
      } else if (holdsMethod(mod, method)) {
        out.wrongBase.push({ where, base: prefix });
      }
    }
  }
  return out;
}

// ─── @stapel pairs ───────────────────────────────────────────────────────────

function pairPackages(scope) {
  const out = new Set();
  for (const mod of scope) {
    for (const spec of mod.imports) {
      // A pair is @stapel/<module>-react; core, tokens and the like issue no requests.
      const m = spec.match(/^(@stapel\/[^/]+-react)(?:\/|$)/);
      if (m) out.add(m[1]);
    }
  }
  return [...out].sort();
}

const pairCache = new Map();

function pairManifest(frontend, pkg) {
  if (pairCache.has(pkg)) return pairCache.get(pkg);
  let data = null;
  const file = path.join(frontend, "node_modules", ...pkg.split("/"), "manifest.json");
  try {
    data = JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    data = null;
  }
  pairCache.set(pkg, data);
  return data;
}

function normOp(p) {
  return String(p).split("?")[0].replace(PARAM_RE, "{}").replace(/\/+$/, "");
}

function pairOperations(frontend, pkg) {
  const data = pairManifest(frontend, pkg);
  if (!data || !data.operations) return null;
  return Object.entries(data.operations).map(([id, op]) => ({ id, method: String(op.method || "GET").toUpperCase(), path: String(op.path || "") }));
}

function installedPairBases(frontend) {
  const bases = new Set();
  const dir = path.join(frontend, "node_modules", "@stapel");
  if (!fs.existsSync(dir)) return bases;
  for (const name of fs.readdirSync(dir)) {
    for (const op of pairOperations(frontend, `@stapel/${name}`) ?? []) {
      const { base } = splitBase(op.path);
      if (base) bases.add(base);
    }
  }
  return bases;
}

function reservedApiBases(frontend) {
  const bases = new Set();
  for (const file of [path.join(frontend, "reserved-paths.json"), path.join(frontend, "..", "reserved-paths.json")]) {
    try {
      const data = JSON.parse(fs.readFileSync(file, "utf8"));
      for (const p of data.reservedPathPrefixes ?? []) {
        // A module mount (/<mod>/api); a bare /api is no module's.
        if (/^\/[^/]+\/api$/.test(String(p).replace(/\/+$/, ""))) bases.add(String(p).replace(/\/+$/, ""));
      }
      break;
    } catch {
      // next location
    }
  }
  return bases;
}

// ─── handlers ────────────────────────────────────────────────────────────────

const HANDLERS = {
  click: ["onClick", "to", "href", "onPress"],
  submit: ["onSubmit", "onFinish"],
  change: ["onChange", "onSelect"],
};
const FORM_HANDLERS = ["onSubmit", "onFinish"];

function enclosingForm(ts, element) {
  let node = element.parent;
  while (node) {
    if (ts.isJsxElement(node)) {
      const opening = node.openingElement;
      const tag = opening.tagName.getText();
      if ((tag === "form" || tag === "Form") && FORM_HANDLERS.some((h) => attribute(ts, opening, h))) {
        return opening;
      }
    }
    node = node.parent;
  }
  return undefined;
}

// The component function around *node*: {name, fn}.
function enclosingComponent(ts, node) {
  let n = node.parent;
  while (n) {
    if (ts.isFunctionDeclaration(n) && n.name) return { name: n.name.text, fn: n };
    if ((ts.isArrowFunction(n) || ts.isFunctionExpression(n)) && n.parent
        && ts.isVariableDeclaration(n.parent) && ts.isIdentifier(n.parent.name)) {
      return { name: n.parent.name.text, fn: n };
    }
    n = n.parent;
  }
  return undefined;
}

// The prop an attribute's expression reads, when it is one of the component's props.
function propName(ts, attr, component) {
  const init = attr.initializer;
  const expr = init && ts.isJsxExpression(init) ? init.expression : undefined;
  if (!expr || !component || !component.fn.parameters.length) return undefined;
  const param = component.fn.parameters[0].name;
  if (ts.isIdentifier(expr) && ts.isObjectBindingPattern(param)) {
    const el = param.elements.find((e) => ts.isIdentifier(e.name) && e.name.text === expr.text);
    if (el) return (el.propertyName && ts.isIdentifier(el.propertyName)) ? el.propertyName.text : expr.text;
  }
  if (ts.isPropertyAccessExpression(expr) && ts.isIdentifier(expr.expression) && ts.isIdentifier(param)
      && expr.expression.text === param.text) {
    return expr.name.text;
  }
  return undefined;
}

// Every JSX element that renders *component* of *home*: [{mod, element, line}].
function usagesOf(component, home, mods, byFile) {
  const out = [];
  for (const mod of mods) {
    let local;
    if (mod === home) {
      local = component;
    } else {
      for (const [name, b] of mod.bindings) {
        if (b.name === component && resolveImport(mod.file, b.spec, byFile) === home.file) local = name;
      }
    }
    if (!local) continue;
    for (const use of mod.jsx) if (use.tag === local) out.push({ mod, ...use });
  }
  return out;
}

// {status: "pass"|"fail"|"unverifiable", text, via: [modules]}
function handlerOf(ts, mod, element, kind, mods, byFile) {
  const names = HANDLERS[kind] ?? HANDLERS.click;
  const own = names.find((h) => attribute(ts, element, h));
  if (own) {
    const component = enclosingComponent(ts, element);
    const prop = propName(ts, attribute(ts, element, own), component);
    if (!prop) return { status: "pass", text: own, via: [] };
    const uses = usagesOf(component.name, mod, mods, byFile);
    const passing = uses.filter((u) => attribute(ts, u.element, prop));
    if (passing.length) {
      return {
        status: "pass",
        text: `${own} = prop ${prop}, passed by <${component.name}> at `
          + passing.map((u) => `${u.mod.rel}:${u.line}`).join(", "),
        via: [...new Set(passing.map((u) => u.mod))],
      };
    }
    if (uses.length) {
      return {
        status: "fail",
        text: `${own} is prop ${prop} of ${component.name}, and no <${component.name}> passes it (`
          + uses.map((u) => `${u.mod.rel}:${u.line}`).join(", ") + ")",
      };
    }
    return { status: "unverifiable", text: `${own} is prop ${prop} of ${component.name}, which no JSX under src/ renders` };
  }
  const isSubmit = ["submit"].includes(attributeValue(ts, element, "type") ?? "")
    || ["submit"].includes(attributeValue(ts, element, "htmlType") ?? "");
  if ((kind === "click" && isSubmit) || kind === "submit") {
    const form = enclosingForm(ts, element);
    if (form) {
      return { status: "pass", text: `${form.tagName.getText()} ${FORM_HANDLERS.find((h) => attribute(ts, form, h))}`, via: [] };
    }
  }
  if (element.attributes.properties.some((p) => ts.isJsxSpreadAttribute(p))) {
    return { status: "unverifiable", text: "no own handler; one may arrive through {...spread} props" };
  }
  return { status: "fail", text: "" };
}

// ─── routes ──────────────────────────────────────────────────────────────────

const PARAM_SEGMENT_RE = /^(<[^>/]+>|\{[^}/]+\}|:[A-Za-z_][\w]*\??)$/;

function routePattern(route) {
  const parts = String(route).replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
  return parts.map((seg) => (PARAM_SEGMENT_RE.test(seg) ? null : seg));
}

function routeDeclared(route, mods) {
  const want = routePattern(route);
  const matches = (literal) => {
    const got = routePattern(literal);
    if (!got.length && want.length) return false;
    if (got.length > want.length) return false;
    if (!got.length && !want.length) return true;
    const tail = want.slice(want.length - got.length);
    return tail.every((seg, i) => (seg === null ? got[i] === null : seg === got[i]));
  };
  for (const mod of mods) {
    if (mod.routes.some((r) => (r === "/" || r === "") ? want.length === 0 : matches(r))) return mod;
  }
  return undefined;
}

// ─── main ────────────────────────────────────────────────────────────────────

const API_BASE_RE = new RegExp(`^(?:https?://[^/${UNKNOWN}]+|${ORIGIN})?((?:/[^/?${UNKNOWN}]+)*?/api)(?=/|$|\\?)`);

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!fs.existsSync(path.join(args.frontend, "package.json"))) {
    fail(`no frontend at ${args.frontend} (no package.json): nothing to check`);
  }
  const ts = loadTypeScript(args.frontend);
  const manifests = loadManifests(args.manifest);
  const src = path.join(args.frontend, "src");
  const files = walk(src);
  if (!files.length) fail(`no source files under ${src}`);
  const mods = files.map((f) => scan(ts, f, args.frontend));
  const byFile = new Map(mods.map((m) => [m.file, m]));
  const ev = new Evaluator(ts, byFile, loadEnv(args.frontend));
  findHelpers(ts, mods, ev);
  evaluateSites(ts, mods, ev);

  // The project's canon API base(s).
  const canon = new Set();
  if (args.apiBase) canon.add(args.apiBase);
  for (const { data } of manifests) {
    if (data.api_base) canon.add(normBase(data.api_base));
    for (const c of data.criteria) {
      for (const page of c.pages ?? []) {
        for (const a of page.actions ?? []) {
          const base = a.request ? splitBase(String(a.request.path || "").split("?")[0]).base : "";
          if (base) canon.add(base);
        }
      }
    }
  }
  const allowed = new Set([...canon, ...installedPairBases(args.frontend), ...reservedApiBases(args.frontend)]);

  const results = [];
  const criteria = {};
  let testidCount = 0;
  let actionCount = 0;
  const record = (task, cid, route, check, status, detail) => {
    const key = task ? `${task}:${cid}` : cid;
    criteria[key] ??= { task, id: cid, ok: true, failed: [], unverifiable: [] };
    const tag = status === true || status === "pass" ? "PASS"
      : status === "unverifiable" ? "UNVERIFIABLE" : "FAIL";
    if (tag === "FAIL") criteria[key].failed.push(`${route} ${check}: ${detail}`);
    if (tag === "UNVERIFIABLE") criteria[key].unverifiable.push(`${route} ${check}: ${detail}`);
    if (tag !== "PASS") criteria[key].ok = false;
    results.push({ tag, line: `${tag} ${cid} ${route} ${check}: ${detail}` });
  };

  const requestCheck = (task, cid, route, id, request, roots, scopeNote) => {
    const scope = reachable(roots, byFile, 2);
    const method = String(request.method ?? "GET").toUpperCase();
    const needle = requestNeedle(request.path);
    const found = classify(scope, needle, method);
    const label = `action ${id} request`;
    const others = scope.filter((m) => !roots.includes(m)).map((m) => m.rel).join(", ");
    if (found.exact.length) {
      record(task, cid, route, label, "pass", `${method} ${needle.full} in ${found.exact[0]}`);
      return;
    }
    const pkgs = pairPackages(scope);
    const silent = [];
    for (const pkg of pkgs) {
      const ops = pairOperations(args.frontend, pkg);
      if (!ops) {
        if (!pairManifest(args.frontend, pkg)) silent.push(pkg);  // a manifest without operations has no backend
        continue;
      }
      const op = ops.find((o) => o.method === method && normOp(o.path) === normOp(needle.full));
      if (op) {
        record(task, cid, route, label, "pass",
          `${method} ${needle.full} declared by ${pkg} (operation ${op.id}), issued inside the pair`);
        return;
      }
    }
    if (found.wrongBase.length) {
      const w = found.wrongBase[0];
      record(task, cid, route, label, "fail",
        `${method} ${needle.tail} at ${w.where} is under ${w.base}, not the canon ${needle.base || "/"}`
        + (found.wrongBase.length > 1 ? ` (+${found.wrongBase.length - 1} more)` : ""));
      return;
    }
    if (found.unverifiable.length) {
      record(task, cid, route, label, "unverifiable", found.unverifiable[0]);
      return;
    }
    if (silent.length) {
      record(task, cid, route, label, "unverifiable",
        `no ${method} ${needle.full} in src/; ${silent.join(", ")} may issue it and ships no manifest.json`);
      return;
    }
    record(task, cid, route, label, "fail",
      `no ${method} ${needle.full} in ${scopeNote} (${others || "none"})`
      + (pkgs.length ? `; not declared by ${pkgs.join(", ")}` : ""));
  };

  for (const { data } of manifests) {
    const task = data.task ?? "";
    for (const criterion of data.criteria) {
      const cid = String(criterion.id ?? "?");
      for (const page of criterion.pages ?? []) {
        const route = String(page.route ?? "?");
        if (page.route !== undefined) {
          const where = routeDeclared(page.route, mods);
          record(task, cid, route, "route", Boolean(where),
            where ? `declared in ${where.rel}` : "no route object or <Route> declares this path");
        }
        const homes = {};
        for (const id of page.testids ?? []) {
          testidCount += 1;
          const owners = mods.filter((m) => m.testids.some((t) => t.id === id));
          if (owners.length === 1) {
            const at = owners[0].testids.find((t) => t.id === id);
            homes[id] = { mod: owners[0], at };
            record(task, cid, route, `testid ${id}`, true, `${owners[0].rel}:${at.line}`);
          } else if (!owners.length) {
            record(task, cid, route, `testid ${id}`, false, "rendered by no module under src/");
          } else {
            record(task, cid, route, `testid ${id}`, false,
              `ambiguous, in ${owners.length} modules: ${owners.map((m) => m.rel).join(", ")}`);
          }
        }
        const first = (page.testids ?? [])[0];
        const pageHome = first ? homes[first] : undefined;
        if (page.h1) {
          if (!pageHome) {
            record(task, cid, route, "h1", false, "no page module (its first testid is not rendered)");
          } else {
            record(task, cid, route, "h1", pageHome.mod.h1,
              pageHome.mod.h1 ? `${pageHome.mod.rel}` : `${pageHome.mod.rel} renders no <h1> or level-1 Title`);
          }
        }
        for (const action of page.actions ?? []) {
          actionCount += 1;
          const id = String(action.testid ?? "?");
          const kind = String(action.handler ?? "click");
          const owners = mods.filter((m) => m.testids.some((t) => t.id === id));
          if (owners.length !== 1) {
            record(task, cid, route, `action ${id}`, false,
              owners.length ? `testid in ${owners.length} modules` : "testid rendered by no module under src/");
            // The request is still looked for from the page module.
            if (action.request && pageHome) {
              requestCheck(task, cid, route, id, action.request, [pageHome.mod],
                `the page module ${pageHome.mod.rel} or the modules it imports`);
            }
            continue;
          }
          const mod = owners[0];
          const at = mod.testids.find((t) => t.id === id);
          const tag = at.element ? at.element.tagName.getText(mod.sf) : "element";
          const handler = at.element ? handlerOf(ts, mod, at.element, kind, mods, byFile)
            : { status: "fail", text: "" };
          const where = `${mod.rel}:${at.line}`;
          if (handler.status === "pass") {
            record(task, cid, route, `action ${id} ${kind}`, "pass", `<${tag}> ${handler.text} at ${where}`);
          } else if (handler.status === "unverifiable" || handler.text) {
            record(task, cid, route, `action ${id} ${kind}`, handler.status, `<${tag}> at ${where}: ${handler.text}`);
          } else {
            record(task, cid, route, `action ${id} ${kind}`, "fail",
              `<${tag}> at ${where} has no ${kind} handler (${(HANDLERS[kind] ?? HANDLERS.click).join(", ")})`
              + (kind === "click" ? " and is not a submit button inside a <form onSubmit>" : ""));
          }
          if (action.request) {
            const roots = [mod, ...(handler.via ?? [])];
            requestCheck(task, cid, route, id, action.request, roots,
              `${roots.map((m) => m.rel).join(", ")} or the modules ${roots.length > 1 ? "they import" : "it imports"}`);
          }
        }
        // Every API path in the page's scope sits under an allowed base.
        if (pageHome && canon.size) {
          const scope = reachable([pageHome.mod], byFile, 2);
          const wrong = [];
          const unsure = [];
          let seen = 0;
          for (const m of scope) {
            for (const p of m.paths) {
              const hit = API_BASE_RE.exec(p.flat);
              if (hit) {
                seen += 1;
                if (!allowed.has(hit[1])) wrong.push(`${m.rel}:${p.line} ${describe(p.parts)}`);
              } else if (/\/api(\/|$)/.test(p.flat) && /[\u0001\u0002]/.test(p.flat.split("/api")[0])) {
                seen += 1;
                unsure.push(`${m.rel}:${p.line} ${describe(p.parts)}`);
              }
            }
          }
          const canonText = [...canon].join(" or ");
          if (wrong.length) {
            record(task, cid, route, "base", "fail",
              `${wrong.length} API path(s) outside the canon ${canonText}: ${wrong.slice(0, 3).join("; ")}`
              + (wrong.length > 3 ? `; +${wrong.length - 3} more` : ""));
          } else if (unsure.length) {
            record(task, cid, route, "base", "unverifiable",
              `base not constant: ${unsure.slice(0, 3).join("; ")}`);
          } else if (seen) {
            record(task, cid, route, "base", "pass", `${seen} API path(s) under ${[...allowed].filter((b) => b).join(", ")}`);
          }
        }
      }
    }
  }
  if (!results.length) fail("the manifest names no route, testid, h1 or action: checked 0");
  for (const r of results) console.log(r.line);
  const failed = results.filter((r) => r.tag === "FAIL").length;
  const unverifiable = results.filter((r) => r.tag === "UNVERIFIABLE").length;
  console.log(`ui-wiring: ${results.length} checks, ${failed} failed, ${unverifiable} unverifiable `
    + `(${testidCount} testids, ${actionCount} actions, ${mods.length} modules scanned`
    + `${canon.size ? `, canon ${[...canon].join(" ")}` : ", no canon base"})`);
  const ok = failed === 0 && unverifiable === 0;
  console.log(`${RESULT_TAG} ${JSON.stringify({
    ok, checks: results.length, failed, unverifiable, protocol: PROTOCOL, criteria: Object.values(criteria),
  })}`);
  process.exit(failed ? 1 : unverifiable ? 3 : 0);
}

main();
